pub fn retry_decision(
    key: &str,
    payload: &str,
    previous: Option<(&str, &str)>,
) -> u16 {
    if key.trim().is_empty() {
        400
    } else {
        match previous {
            Some((old_key, old_payload)) if old_key == key => {
                if old_payload == payload {
                    200
                } else {
                    409
                }
            }
            _ => 201,
        }
    }
}

fn main() {
    assert_eq!(retry_decision("k", "title", None), 201, "case 1");
    assert_eq!(retry_decision("", "title", None), 400, "case 2");
    assert_eq!(
        retry_decision("k", "title", Some(("k", "title"))),
        200,
        "case 3"
    );
    assert_eq!(
        retry_decision("k", "other", Some(("k", "title"))),
        409,
        "case 4"
    );
    assert_eq!(
        retry_decision("new", "x", Some(("old", "x"))),
        201,
        "case 5"
    );
    println!("worked example passed");
}

